<?php
session_start();
require_once __DIR__ . '/config/database.php';
if (empty($_SESSION['demo_limpio'])) { try { $pdo->prepare("UPDATE empresas SET nombre='GIUBOL' WHERE LOWER(TRIM(nombre))='giubol demo'")->execute(); $pdo->prepare("UPDATE clientes SET correo=REPLACE(correo,'@demo.com','@ejemplo.com') WHERE correo LIKE '%@demo.com'")->execute(); } catch (Exception $e) {} $_SESSION['demo_limpio']=1; }
$empresa = $pdo->query("SELECT * FROM empresas WHERE activo = 1 ORDER BY id_empresa ASC LIMIT 1")->fetch() ?: ['id_empresa'=>1,'nombre'=>'GIUBOL','telefono'=>'','correo'=>'','ciudad'=>'','estado'=>''];
$empresa['nombre']=trim(preg_replace('/\s+/',' ',preg_replace('/\bdemo\b/i','',(string)$empresa['nombre']))) ?: 'GIUBOL';
$id_empresa_publica = (int)$empresa['id_empresa'];
$st = $pdo->prepare("SELECT p.id_producto,p.nombre,p.tipo,p.unidad,p.precio_venta,p.stock,c.nombre AS categoria FROM productos p LEFT JOIN categorias c ON c.id_categoria=p.id_categoria WHERE p.id_empresa=? AND p.activo=1 ORDER BY (c.id_categoria IS NULL), c.id_categoria, CASE p.tipo WHEN 'Servicio' THEN 2 WHEN 'Producto' THEN 1 ELSE 0 END, p.nombre LIMIT 400");
$st->execute([$id_empresa_publica]); $productos_publicos = $st->fetchAll();
$logueado = isset($_SESSION['id_usuario']) && (int)($_SESSION['id_empresa'] ?? 0) === $id_empresa_publica;
function e($v){ return htmlspecialchars((string)$v, ENT_QUOTES, 'UTF-8'); }
function lower_es($v){ $v=strtolower((string)$v); return strtr($v,['Á'=>'á','É'=>'é','Í'=>'í','Ó'=>'ó','Ú'=>'ú','Ü'=>'ü','Ñ'=>'ñ']); }
$grupos = []; foreach ($productos_publicos as $p_) { $grupos[$p_['categoria'] ?: $p_['tipo']][] = $p_; } unset($p_);
