<script>
(function(){
 const menu=document.querySelector('.mobile-menu');menu?.addEventListener('click',function(){const nav=document.querySelector('.nav-inner');const open=nav.classList.toggle('nav-open');this.setAttribute('aria-expanded',open?'true':'false')});
 document.querySelectorAll('a[href^="#"]').forEach(a=>a.addEventListener('click',e=>{const target=document.querySelector(a.getAttribute('href'));if(target){e.preventDefault();target.scrollIntoView({behavior:'smooth',block:'start'});document.querySelector('.nav-inner')?.classList.remove('nav-open')}}));
 const room=document.getElementById('roomPreview'), picker=document.getElementById('finishPicker'); if(!room)return;
 const wall=document.getElementById('wallFinish'), floor=document.getElementById('floorFinish'), width=document.getElementById('roomWidth'), depth=document.getElementById('roomDepth'); let space='sala', style='moderno', accent='#c99a2e', view='principal';
 const labels={sala:'Sala',cocina:'Cocina',bano:'Baño',recamara:'Recámara',exterior:'Exterior'}, styles={moderno:'Moderno',minimalista:'Minimalista',industrial:'Industrial',calido:'Natural cálido'};
 function selected(){return picker?.options[picker.selectedIndex]||null}
 function update(){const o=selected(), w=Number(width?.value||5),d=Number(depth?.value||6),area=w*d;document.getElementById('widthValue').textContent=w;document.getElementById('depthValue').textContent=d;document.getElementById('areaValue').textContent=area;document.getElementById('roomDimensions').textContent=`${w} × ${d} m · ${area} m²`;document.getElementById('summaryArea').textContent=area+' m²';document.getElementById('previewSpaceLabel').textContent=labels[space]+' · Estilo '+styles[style].toLowerCase();document.getElementById('summaryStyle').textContent=styles[style];room.dataset.space=space;room.dataset.style=style;room.dataset.view=view;room.style.setProperty('--accent',accent);room.style.setProperty('--room-scale',String(Math.max(.85,Math.min(1.2,area/30))));room.classList.remove('wall-pintura','wall-madera','wall-marmol','wall-ladrillo','wall-concreto','floor-ceramica','floor-madera','floor-marmol','floor-concreto','floor-granito');room.classList.add('wall-'+(wall?.value||'pintura'),'floor-'+(floor?.value||'ceramica'));
 if(o){document.getElementById('finishName').textContent=o.dataset.name;document.getElementById('finishMeta').textContent=o.dataset.type+' · '+o.dataset.unit;document.getElementById('roomLabel').textContent=o.dataset.name;document.getElementById('summaryMaterial').textContent=o.dataset.name;const cfg={espacio:labels[space],estilo:styles[style],muros:wall?.selectedOptions[0]?.text||'Pintura mate',piso:floor?.selectedOptions[0]?.text||'Cerámica',color:accent,ancho:w,largo:d,area,material:o.dataset.name,producto:o.value};const url=new URL('solicitar.php',location.href);url.searchParams.set('tipo','Diseno');url.searchParams.set('producto',o.value);url.searchParams.set('config',JSON.stringify(cfg));document.getElementById('finishQuoteLink').href=url.pathname+url.search;
 } else {document.getElementById('finishName').textContent='Catálogo por configurar';document.getElementById('summaryMaterial').textContent='Por definir';}
 }
 document.querySelectorAll('[data-space]').forEach(b=>b.addEventListener('click',()=>{space=b.dataset.space;document.querySelectorAll('[data-space]').forEach(x=>x.classList.toggle('active',x===b));update()}));
 document.querySelectorAll('[data-style]').forEach(b=>b.addEventListener('click',()=>{style=b.dataset.style;document.querySelectorAll('[data-style]').forEach(x=>x.classList.toggle('active',x===b));update()}));
 document.querySelectorAll('[data-color]').forEach(b=>b.addEventListener('click',()=>{accent=b.dataset.color;document.querySelectorAll('[data-color]').forEach(x=>x.classList.toggle('active',x===b));update()}));
 document.querySelectorAll('[data-view]').forEach(b=>b.addEventListener('click',()=>{view=b.dataset.view;document.querySelectorAll('[data-view]').forEach(x=>x.classList.toggle('active',x===b));update()}));
 [picker,wall,floor,width,depth].forEach(el=>el?.addEventListener('input',update));[picker,wall,floor].forEach(el=>el?.addEventListener('change',update));
 update();
})();
</script>
<script>
(function(){
 const sec=document.getElementById('materiales'),chips=[...document.querySelectorAll('.cat-chip')],blocks=[...document.querySelectorAll('.cat-block')],empty=document.getElementById('catalogEmpty'),search=document.getElementById('materialSearch');
 if(!blocks.length)return;
 function show(cat){chips.forEach(c=>{const on=c.dataset.cat===cat;c.classList.toggle('active',on);c.setAttribute('aria-selected',on?'true':'false')});blocks.forEach(b=>b.classList.toggle('active',b.dataset.catBlock===cat))}
 function filter(){const q=(search?search.value:'').trim().toLocaleLowerCase('es');sec.classList.toggle('is-searching',q!=='');let hits=0;
  blocks.forEach(b=>{let n=0;b.querySelectorAll('[data-material-card]').forEach(card=>{const ok=q===''||card.dataset.name.includes(q)||card.dataset.category.includes(q);card.hidden=!ok;if(ok)n++});hits+=n;b.classList.toggle('has-hits',n>0)});
  if(empty)empty.hidden=!(q!==''&&hits===0)}
 chips.forEach(c=>c.addEventListener('click',()=>{if(search&&search.value){search.value='';filter()}show(c.dataset.cat)}));
 document.querySelectorAll('[data-more]').forEach(btn=>btn.addEventListener('click',()=>{const open=btn.closest('.cat-block').classList.toggle('expanded');btn.textContent=open?'Ver menos':btn.dataset.label}));
 search?.addEventListener('input',filter);
})();
</script>
</body></html>
